// Normalize inbound payload for Watchdog audit.
// Register Scorpion is leftover — NOT the audit sink.
const body = $json.body || $json;

const serviceName = body.serviceName || body.service_name || body.name || 'hive-golden-path-smoke';
const version = body.version || body.ver || '1.0.0';
const host = body.host || body.hostname || 'evenslouis.ca';
const port = Number(body.port) || 443;
const protocol = body.protocol || 'https';
const status = body.status || 'healthy';

const metadata = {
  correlationId: body.correlationId || body.correlation_id || `gp_${Date.now()}`,
  source: body.source || 'hive-golden-path',
  goal: body.goal || 'smoke-test-registration',
  summary: body.summary || `Golden path smoke from ${serviceName}`,
  jobType: body.jobType || body.job_type || 'maintenance',
  triggeredAt: new Date().toISOString()
};

const tags = body.tags || ['hive', 'golden-path', 'smoke-test'];

return [{
  json: {
    registerPayload: {
      serviceName,
      version,
      host,
      port,
      protocol,
      status,
      metadata,
      tags
    },
    originalInput: body
  }
}];

// Evaluate Watchdog audit attempt. Register Scorpion is leftover — NOT the audit sink.
const built = $('Build Register Payload').first().json;
const result = $input.first().json;
const statusCode = result.statusCode || result.code || 200;
const success = statusCode >= 200 && statusCode < 300;

return [{
  json: {
    audited: true,
    sink: 'grok-watchdog',
    leftoverScorpion: 'NOT the audit sink',
    statusCode,
    watchdogOk: success,
    correlationId: built.registerPayload?.metadata?.correlationId || null,
    message: success ? 'Watchdog audit posted (or continueOnFail)' : (result.message || result.error || 'Watchdog POST failed soft')
  }
}];
